-- Artefacts et mascottes (généré par gen_reliques.py)
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS `custom_relique_objet` (`entry` INT UNSIGNED NOT NULL, `type` TINYINT UNSIGNED NOT NULL, PRIMARY KEY (`entry`)) ENGINE=InnoDB DEFAULT CHARSET=utf8;
DROP TABLE IF EXISTS `custom_relique_mascotte`;
CREATE TABLE `custom_relique_mascotte` (`entry` INT UNSIGNED NOT NULL, `stat1` VARCHAR(4) NOT NULL, `stat2` VARCHAR(4) NOT NULL, PRIMARY KEY (`entry`)) ENGINE=InnoDB DEFAULT CHARSET=utf8;
DROP TABLE IF EXISTS `custom_relique_recette`;
CREATE TABLE `custom_relique_recette` (`couleur` TINYINT UNSIGNED NOT NULL, `palier` TINYINT UNSIGNED NOT NULL, `objet1` INT UNSIGNED NOT NULL DEFAULT 0, `nombre1` INT UNSIGNED NOT NULL DEFAULT 0, `objet2` INT UNSIGNED NOT NULL DEFAULT 0, `nombre2` INT UNSIGNED NOT NULL DEFAULT 0, `objet3` INT UNSIGNED NOT NULL DEFAULT 0, `nombre3` INT UNSIGNED NOT NULL DEFAULT 0, `objet4` INT UNSIGNED NOT NULL DEFAULT 0, `nombre4` INT UNSIGNED NOT NULL DEFAULT 0, `argent` INT UNSIGNED NOT NULL DEFAULT 0, PRIMARY KEY (`couleur`, `palier`)) ENGINE=InnoDB DEFAULT CHARSET=utf8;
DELETE FROM custom_relique_objet;
DELETE FROM item_template WHERE entry BETWEEN 992000 AND 992299;
DELETE FROM item_loot_template WHERE entry BETWEEN 992000 AND 992299;
DELETE FROM reference_loot_template WHERE entry BETWEEN 99300 AND 99309;
DELETE FROM creature_loot_template WHERE item BETWEEN 992000 AND 992299 OR item BETWEEN 99300 AND 99309;
